"use client";

import { useEffect, useState } from "react";

import { VouVerEsse } from "@/features/como-foi/components/vou-ver-esse";
import { MAX_TROCAS, type Clima } from "@/features/metricas/eventos";
import { EsseNao } from "@/features/noite/components/esse-nao";
import { FilmeDestaque, type FilmeNaTela } from "@/features/noite/components/filme-destaque";
import { OpcaoNoite } from "@/features/noite/components/opcao-noite";
import { useSessaoNoite } from "@/features/noite/components/sessao-noite";
import type { MotivoTroca } from "@/features/noite/estado";

type Props = {
  respostas: Clima;
  /** Trocas já feitas nesta sessão (0 na primeira recomendação). */
  trocas: number;
  destaque: FilmeNaTela;
  /** As 2 opções menores, depois de uma troca. */
  opcoes: FilmeNaTela[];
  /** URL da próxima rodada por motivo de "Esse não", ou `null` no limite. */
  proximas: Record<MotivoTroca, string> | null;
};

/**
 * Tela do resultado: o destaque e as opções, cada um com "Vou ver esse!", e "Esse não".
 * Na primeira rodada, conclui o wizard. Depois da escolha, só fica a confirmação do escolhido.
 */
export function ResultadoNoite({ respostas, trocas, destaque, opcoes, proximas }: Props) {
  const { concluir, marcarEscolha } = useSessaoNoite();
  const [escolhido, setEscolhido] = useState<number | null>(null);

  useEffect(() => {
    if (trocas === 0) concluir(respostas);
  }, [concluir, respostas, trocas]);

  const vouVer = (filme: FilmeNaTela) =>
    (escolhido === null || escolhido === filme.id) && (
      <VouVerEsse
        tmdbId={filme.id}
        titulo={filme.titulo}
        trocas={trocas}
        aoEscolher={() => {
          setEscolhido(filme.id);
          marcarEscolha();
        }}
      />
    );

  return (
    <div className="flex flex-col gap-10">
      <FilmeDestaque
        filme={destaque}
        acoes={
          <div className="flex flex-col gap-3 sm:flex-row sm:items-start">
            {vouVer(destaque)}
            {escolhido === null && (
              <EsseNao
                proximas={proximas}
                trocasRestantes={MAX_TROCAS - trocas}
                destaque={destaque}
              />
            )}
          </div>
        }
      />
      {opcoes.length > 0 && (
        <section aria-labelledby="ou-talvez" className="flex flex-col gap-3">
          <h2 id="ou-talvez" className="text-xl tracking-tight">
            Ou talvez
          </h2>
          <ul className="flex flex-col gap-3">
            {opcoes.map((filme) => (
              <li key={filme.id}>
                <OpcaoNoite filme={filme} acao={vouVer(filme)} />
              </li>
            ))}
          </ul>
        </section>
      )}
    </div>
  );
}
import type { ReactNode } from "react";

import {
  anoEDuracao,
  PosterNoite,
  type FilmeNaTela,
} from "@/features/noite/components/filme-destaque";
import { TerminaAs } from "@/features/noite/components/termina-as";

/** Uma das 2 opções menores que aparecem depois de "Esse não". `acao` é o "Vou ver esse!". */
export function OpcaoNoite({ filme, acao }: { filme: FilmeNaTela; acao?: ReactNode }) {
  return (
    <article
      aria-labelledby={`opcao-${filme.id}`}
      className="border-border bg-card flex gap-4 rounded-xl border p-3"
    >
      <PosterNoite filme={filme} className="w-20 sm:w-24" />
      <div className="flex min-w-0 flex-1 flex-col gap-1.5">
        <h3 id={`opcao-${filme.id}`} className="leading-tight font-medium break-words">
          {filme.titulo}
        </h3>
        <p className="text-muted-foreground text-sm">
          {[anoEDuracao(filme), filme.provedor?.nome].filter(Boolean).join(" · ")}
        </p>
        {filme.duracaoMin && <TerminaAs duracaoMin={filme.duracaoMin} />}
        {acao}
      </div>
    </article>
  );
}
import { z } from "zod";

/** Limite de trocas do wizard (pedido do cliente, 3.2). */
export const MAX_TROCAS = 5;

export const MOTIVOS_TROCA = ["ja-vi", "nao-e-o-clima", "muito-longo", "outro"] as const;
export const RESPOSTAS_COMO_FOI = ["amei", "gostei", "nao-gostei", "nao-vi"] as const;
export const ORIGENS_TRAILER = ["filme", "noite"] as const;
export const ETAPAS_WIZARD = ["perguntas", "resultado"] as const;

export type OrigemTrailer = (typeof ORIGENS_TRAILER)[number];

const semDados = z.strictObject({}).default({});

/**
 * Lista fechada de eventos e os dados de cada um (SPEC/2026-11-18-metricas.md).
 * Objetos estritos: qualquer chave a mais, como o clima do wizard, é recusada.
 */
export const eventoSchema = z.discriminatedUnion("nome", [
  z.object({ nome: z.literal("wizard_iniciado"), dados: semDados }),
  z.object({ nome: z.literal("wizard_concluido"), dados: semDados }),
  z.object({
    nome: z.literal("wizard_troca"),
    dados: z.strictObject({ motivo: z.enum(MOTIVOS_TROCA) }),
  }),
  z.object({
    nome: z.literal("wizard_escolheu"),
    dados: z.strictObject({ trocas: z.number().int().min(0).max(MAX_TROCAS) }),
  }),
  z.object({
    nome: z.literal("wizard_abandonado"),
    dados: z.strictObject({ etapa: z.enum(ETAPAS_WIZARD) }),
  }),
  z.object({ nome: z.literal("como_foi_exibido"), dados: semDados }),
  z.object({
    nome: z.literal("como_foi_respondido"),
    dados: z.strictObject({ resposta: z.enum(RESPOSTAS_COMO_FOI) }),
  }),
  z.object({
    nome: z.literal("trailer_aberto"),
    dados: z.strictObject({ origem: z.enum(ORIGENS_TRAILER) }),
  }),
]);

/** Evento como quem registra escreve (`dados` pode faltar nos eventos sem dados). */
export type Evento = z.input<typeof eventoSchema>;
export type NomeEvento = Evento["nome"];

/** Respostas do wizard contadas sem vínculo com a pessoa. */
export const CLIMAS = {
  humor: ["cansado", "animado", "pra-baixo", "nostalgico", "ansioso", "de-boa"],
  experiencia: ["rir", "emocionar", "susto", "tenso", "pensar", "distrair"],
  companhia: ["sozinho", "a-dois", "familia", "amigos"],
} as const;

export type Pergunta = keyof typeof CLIMAS;

export const climaSchema = z.object({
  humor: z.enum(CLIMAS.humor),
  experiencia: z.enum(CLIMAS.experiencia),
  companhia: z.enum(CLIMAS.companhia),
});

export type Clima = z.infer<typeof climaSchema>;
